["default"] = false,
["width"] = 1,
["name"] = "항상 표시",
["useDesc"] = true,
["key"] = "alwaysShow",
["desc"] = "특임조에 내가 포함되어 있지 않아도 항상 순서를 표시합니다.",
},
},
["config"] = {
