["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.config.duration,\n            expirationTime = GetTime() + aura_env.config.duration,\n            GUID = WeakAuras.myGUID,\n            autoHide = true\n        }\n    elseif event == \"LIQUID_DEVOURERS_IRE_ASSIGNMENT\" then\n        local dispelleeGUID, dispellerGUID = ...\n        \n        if dispellerGUID ~= WeakAuras.myGUID then return end\n        \n        allstates[dispelleeGUID] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.config.duration,\n            expirationTime = GetTime() + aura_env.config.duration,\n            GUID = dispelleeGUID,\n            autoHide = true\n        }\n        \n        return true\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and spellID == 1222232 then -- Devourer's Ire\n            local state = allstates[destGUID]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    end\nend",
