["Galactic Smash markers (requires AuraUpdater)"] = {
["wagoID"] = "Rz5kTzQc7",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = true,
["key"] = "tts",
["name"] = "음성 재생",
["useDesc"] = false,
["width"] = 1,
},
},
["preferToUpdate"] = false,
["customText"] = "\n\n",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["customTextUpdate"] = "update",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
["do_glow"] = true,
},
["finish"] = {
["do_message"] = false,
},
["init"] = {
["do_custom_load"] = false,
["custom"] = "aura_env.enabled = C_AddOns.IsAddOnLoaded(\"AuraUpdater\") or C_AddOns.IsAddOnLoaded(\"LiquidMedia\")\n\n\nlocal auraData = WeakAuras.GetData(\"Galactic Smash background (requires AuraUpdater)\")\n\nlocal MAP_WIDTH = auraData and auraData.width or 200\nlocal MAP_HEIGHT = auraData and auraData.height or 200\nlocal MARKER_SIZE = 0.07\n\n-- Relative to center\nlocal INNER_RING_DISTANCE = 0.185\nlocal MIDDLE_RING_DISTANCE = 0.298\nlocal OUTER_RING_DISTANCE = 0.42\n\nlocal MAP_CENTER_OFFSET_X = 0 * MAP_WIDTH\nlocal MAP_CENTER_OFFSET_Y = 0.01 * MAP_HEIGHT\n\n-- Heroic\nlocal heroicDegrees = {\n    [1] = 228,\n    [2] = 116,\n}\n\nlocal heroicDistances = {\n    [1] = INNER_RING_DISTANCE,\n    [2] = MIDDLE_RING_DISTANCE,\n}\n\nlocal heroicPositions = {}\n\nfor i = 1, 2 do\n    local degree = heroicDegrees[i]\n    local distance = heroicDistances[i]\n    \n    heroicPositions[i] = {\n        math.cos(math.rad(degree)) * distance * MAP_WIDTH + MAP_CENTER_OFFSET_X,\n        math.sin(math.rad(degree)) * distance * MAP_HEIGHT + MAP_CENTER_OFFSET_Y,\n    }\nend\n\n-- Mythic\nlocal mythicDegrees = {\n    [1] = 270,\n    [2] = 0,\n    [4] = 130,\n    [7] = -27,\n    [8] = 0,\n}\n\nlocal mythicDistances = {\n    [1] = OUTER_RING_DISTANCE,\n    [2] = MIDDLE_RING_DISTANCE,\n    [4] = MIDDLE_RING_DISTANCE,\n    [7] = INNER_RING_DISTANCE,\n    [8] = OUTER_RING_DISTANCE,\n}\n\nlocal mythicPositions = {}\n\nfor i = 1, 8 do\n    if mythicDegrees[i] then\n        local degree = mythicDegrees[i]\n        local distance = mythicDistances[i]\n        \n        mythicPositions[i] = {\n            math.cos(math.rad(degree)) * distance * MAP_WIDTH + MAP_CENTER_OFFSET_X,\n            math.sin(math.rad(degree)) * distance * MAP_HEIGHT + MAP_CENTER_OFFSET_Y,\n        }\n    end\nend\n\nfunction aura_env:CreateStates(allstates, duration)\n    local positions = aura_env.isMythic and mythicPositions or heroicPositions\n    \n    for mark, position in pairs(positions) do\n        allstates[string.format(\"mark%d\", mark)] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = duration,\n            expirationTime = GetTime() + duration,\n            type = \"MARKER\",\n            index = mark + 1,\n            texture = string.format(\"Interface/TargetingFrame/UI-RaidTargetingIcon_%d\", mark),\n            width = MARKER_SIZE * MAP_WIDTH,\n            height = MARKER_SIZE * MAP_HEIGHT,\n            position = position,\n            autoHide = true\n        }\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if not aura_env.enabled then return end\n    \n    if event == \"OPTIONS\" then\n        aura_env.isMythic = true\n        \n        aura_env:CreateStates(allstates, 1)\n    elseif event == \"LIQUID_GALACTIC_SMASH_ASSIGNMENT\" then\n        local _, _, duration = ...\n        \n        aura_env:CreateStates(allstates, duration or 1)\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        local _, _, difficultyID = ...\n        \n        aura_env.isMythic = difficultyID == 16\n    end\nend",
["events"] = "LIQUID_GALACTIC_SMASH_ASSIGNMENT, ENCOUNTER_START",
["check"] = "event",
["unit"] = "player",
["customVariables"] = "{\n    type = {\n        display = \"Type\",\n        type = \"select\",\n        values = {\n            BACKGROUND = \"Background\",\n            MARKER = \"Marker\",\n            UNASSIGNED = \"Unassigned\",\n            ASSIGNED = \"Assigned\",\n        }\n    }\n}",
