["custom"] = "function (e,message,source)\n    \n    if message == nil then return false end;\n    \n    -- Channels\n    local channels = aura_env.config['track_channels'];\n    local channels_alias = {\n        \"GUILD\",\n        \"WHISPER\",\n        \"SAY\",\n        \"PARTY\",\n        \"PARTY_LEADER\",\n        \"INSTANCE_CHAT\",\n        \"INSTANCE_CHAT_LEADER\",\n        \"RAID\",\n        \"RAID_WARNING\",\n        \"RAID_LEADER\"\n    }\n    \n    -- Ignore Self\n    if (aura_env.config['ignore_self'] == true) then\n        if string.match(string.lower(source),string.lower(UnitName(\"player\"))) then\n            return false \n        end\n    end\n    \n    -- If \"track channels\" config exists\n    if (aura_env.config['track_channels']) then\n        \n        for k, v in pairs(channels) do\n            if string.match(e,'CHAT_MSG_'..channels_alias[k]) then\n                if (not channels[k]) then\n                    -- Channel matched, but not tracked\n                    return false\n                end;\n                -- Channel matched and tracked, so we proceed\n            end;\n        end;\n        \n    end;\n    \n    \n    -- Trim\n    local function trim(s)\n        return (string.gsub(s, \"^%s*(.-)%s*$\", \"%1\"))\n    end\n    \n    -- Split\n    local function split(s, delimiter)\n        local result = {};\n        for match in (s..delimiter):gmatch(\"(.-)\"..delimiter) do\n            table.insert(result, match);\n        end\n        return result;\n    end\n    \n    local function checkIgnored(message)\n        \n        if (aura_env.config['ignore_list_toggle'] == true) then\n            \n            local ignored = {}\n            ignored = split(aura_env.config['ignore_list'], \",\");\n            \n            for k, v in pairs(ignored) do\n                \n                if string.match(trim(string.lower(message)),trim(string.lower(v))) then\n                    return true\n                end;\n                \n            end\n            \n        end\n        \n    end\n    \n    -- Match Name\n    if (aura_env.config['match_name'] == true) then\n        \n        if string.match(string.lower(message),string.lower(UnitName(\"player\"))) then\n            if not checkIgnored(message) then\n                return true\n            end\n        end;\n        \n    end\n    \n    -- Match Nicknames\n    if (aura_env.config['match_nicknames'] == true) then\n        \n        local nicknames = {}\n        nicknames = split(aura_env.config['nicknames'], \",\");\n        \n        for k, v in pairs(nicknames) do\n            \n            if string.match(trim(string.lower(message)),trim(string.lower(v))) then\n                if not checkIgnored(message) then\n                    return true\n                end\n            end;\n            \n        end\n        \n    end\n    \nend;",
["events"] = "CHAT_MSG_WHISPER,CHAT_MSG_GUILD,CHAT_MSG_SAY,CHAT_MSG_PARTY,CHAT_MSG_RAID,CHAT_MSG_RAID_LEADER,CHAT_MSG_RAID_WARNING,CHAT_MSG_INSTANCE_CHAT,CHAT_MSG_INSTANCE_CHAT_LEADER",
