["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.counter = {}\naura_env.specifiedValues = {}\naura_env.specifiedSpellID = {}\naura_env.Callback = {}\nWeakAuras.RegisterBigWigsTimer()\nlocal reset = {\n    [3] = 1,\n    [4] = 2,\n    [5] = 3,\n    [6] = 4,\n    [7] = 5,\n}\n\nlocal aura_env = aura_env\nif BigWigsLoader then \n    local num = aura_env.config.resetCounter\n    if aura_env.config.hideBW then\n        local f = function(event,addon,bar)\n            bar.candyBarBar:SetAlpha(0) \n            bar.candyBarIconFrame:SetAlpha(0)\n            C_Timer.After(0.15, function() bar.candyBarBar:SetAlpha(0) bar.candyBarIconFrame:SetAlpha(0) end)\n        end\n        BigWigsLoader.RegisterMessage(aura_env.Callback, \"BigWigs_BarCreated\", f)\n        BigWigsLoader.RegisterMessage(aura_env.Callback, \"BigWigs_BarEmphasized\", f)\n    end\n    if num ~= 1 then\n        local fun = function(event,addon,phase)\n            if event == \"BigWigs_SetStage\" then\n                local num = aura_env.config.resetCounter\n                if\n                (\n                    num == 2\n                    or\n                    reset[num] and \n                    reset[num] == phase\n                )\n                then\n                    aura_env.counter = {}\n                end\n            end\n        end\n        BigWigsLoader.RegisterMessage(aura_env.Callback, \"BigWigs_SetStage\", fun)\n    end\nend",
["do_custom"] = true,
