["sparkHidden"] = "NEVER",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    duration = duration,\n    expirationTime = true,\n    emphasized = \"bool\",\n    isCast = \"bool\",\n    customName = \"string\",\n    barName = \"string\",\n    spellID = \"string\",\n    count = \"number\",\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates,event,bar)\n    if event == \"ENCOUNTER_START\" then\n        aura_env.counter = {}\n        aura_env.customNames = {}\n        for k,v in pairs{strsplit(\",\", aura_env.config.specifiedValues)} do aura_env.specifiedValues[v] = true end\n        for k,v in pairs{strsplit(\",\", aura_env.config.specifiedSpellID)} do aura_env.specifiedSpellID[v] = true end\n        for k,v in pairs(aura_env.config.customBarNames) do\n            for i = 1, 4 do\n                aura_env.customNames[v[\"curBar\"..i]] = v[\"custBar\"..i]\n            end\n        end\n    end\n    if event == \"BigWigs_StartBar\" then\n        if bar then\n            local b = WeakAuras.GetBigWigsTimerById(bar)\n            local duration = b.duration\n            local expiration = b.expirationTime\n            local icon = b.icon\n            local text = b.text\n            local spellID = b.spellId\n            local isCast = b.cast\n            local count = tonumber(b.count)\n            local emphasized = b.emphasized\n            local state = allstates[bar]\n            if (not aura_env.config.excludeCast or aura_env.config.excludeCast and not isCast) then\n                local output = text\n                if not isCast then\n                    output = string.gsub(text,\"%s%(%d+%)\", \"\")\n                    if count == 0 then\n                        if not aura_env.counter[output] then\n                            aura_env.counter[output] = 1\n                        else\n                            aura_env.counter[output] = aura_env.counter[output] + 1\n                        end\n                    end\n                else\n                    output = text\n                end\n                if (\n                    aura_env.config.enableSpecified \n                    and aura_env.config.specifiedValues \n                    and\n                    (\n                        aura_env.specifiedValues[tostring(aura_env.counter[output])]\n                        or aura_env.specifiedValues[tostring(count)] \n                    )\n                )\n                or not aura_env.config.enableSpecified then\n                    if (\n                        aura_env.config.enableSpellID\n                        and aura_env.config.specifiedSpellID\n                        and\n                        (\n                            aura_env.specifiedSpellID[spellID]\n                            or aura_env.specifiedSpellID[output]\n                            or string.match(aura_env.config.specifiedSpellID, string.gsub(output, \" %(%d+%)\", \"\"))\n                        )\n                    )\n                    or not aura_env.config.enableSpellID then\n                        local counter = isCast and count or aura_env.counter[output]\n                        allstates[bar] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"timed\",\n                            duration = duration,\n                            expirationTime = duration + GetTime(),\n                            icon = icon,\n                            barName  = output,\n                            customName = aura_env.customNames[output] or count > 0 and aura_env.customNames[output..\" (\"..count..\")\"] or counter and aura_env.customNames[output..\" (\"..counter..\")\"],\n                            emphasized = emphasized,\n                            isCast = isCast,\n                            spellID = spellID,\n                            count = counter or count > 0 and count,\n                            autoHide = true,\n                            resort = true,\n                        }\n                    end\n                end\n            end\n        end\n    elseif event == \"BigWigs_StopBar\" then\n        local state = allstates[bar] \n        if state then\n            state.show = false\n            state.changed = true\n        end\n    elseif event == \"BigWigs_PauseBar\" then\n        local state = allstates[bar] \n        if state then\n            state.remaining = state.expirationTime - GetTime()\n            state.changed = true\n            state.paused = true\n        end\n    elseif event == \"BigWigs_ResumeBar\" then\n        local state = allstates[bar]\n        if state then\n            state.paused = false\n            state.expirationTime = GetTime() + (state.remaining or 0)\n            state.changed = true\n            return true\n        end\n    end\n    return true\nend",
