["backdropInFront"] = false,
["customText"] = "function()\n    if aura_env.state and aura_env.state.barName then\n        local count = aura_env.state.count\n        local name = aura_env.state.barName\n        local customName = aura_env.customNames[name] or aura_env.customNames[name.. \" (\"..count..\")\"]\n        if customName then\n            return count and customName..\" (\"..count..\")\" \n        elseif name and count then\n            return name..\" (\"..count..\")\"\n        else\n            return name\n        end\n    end\nend",
