["custom"] = "function(allstates, event, ...)\n    if not aura_env.enabled then return end\n    \n    if event == \"OPTIONS\" then\n        aura_env.isMythic = true\n        \n        local assignmentTypes = {\"RANGED\", \"MELEE\", \"TANK\"}\n        local assignmentType = assignmentTypes[math.random(3)]\n        local set = math.random(3)\n        \n        aura_env:CreateStates(allstates, set, assignmentType, 1)\n    elseif event == \"LIQUID_GALACTIC_SMASH_ASSIGNMENT\" then\n        local set, assignmentType, duration = ...\n        \n        aura_env:CreateStates(allstates, set, assignmentType, duration)\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        local _, _, difficultyID = ...\n        \n        aura_env.isMythic = difficultyID == 16\n    end\nend",
