["The Hunt soak assignments"] = {
["outline"] = "OUTLINE",
["wagoID"] = "Rz5kTzQc7",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    local assignment = aura_env.state and aura_env.state.assignment or 1\n    \n    return CreateTextureMarkup(6035307, 64, 64, 0, 0, 5/64, 59/64, 5/64, 59/64), string.format(\"|cffed2850%d|r\", assignment)\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.immuneSpellIDs = {\n    [45438] = true, -- Ice Block\n    [196555] = true, -- Netherwalk\n    [186265] = true, -- Turtle\n    [642] = true, -- Divine Shield\n    [47585] = true, -- Dispersion\n    [31224] = true, -- Cloak of Shadows\n}\n\nfunction aura_env:ReadNote()\n    aura_env.assignment = nil\n    \n    for lineCount, line in LiquidWeakAuras:IterateNoteAssignment(\"Hunt\") do\n        local _, containsPlayerGUID = LiquidWeakAuras:LineToGUIDArray(line)\n        \n        if containsPlayerGUID then\n            aura_env.assignment = lineCount\n        end\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["events"] = "CLEU:SPELL_AURA_APPLIED, ENCOUNTER_START",
["spellIds"] = {
},
["custom_type"] = "stateupdate",
["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 6.3,\n            expirationTime = GetTime() + 6.3,\n            assignment = math.random(3),\n            autoHide = true\n        }\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" then\n            if spellID == 1227847 then -- The Hunt\n                aura_env.count = aura_env.count + 1\n                \n                if aura_env.count == 4 then\n                    aura_env.count = 1\n                end\n                \n                if aura_env.count == aura_env.assignment then\n                    allstates[destGUID] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        duration = 6.3,\n                        expirationTime = GetTime() + 6.3,\n                        assignment = aura_env.count,\n                        autoHide = true\n                    }\n                    \n                    if aura_env.config.tts then\n                        LiquidWeakAuras:PlaySound(\"soak\")\n                    end\n                    \n                    return true\n                end\n            elseif aura_env.immuneSpellIDs[spellID] then\n                local state = allstates[destGUID]\n                \n                if state then\n                    state.show = false\n                    state.changed = true\n                    \n                    return true\n                end\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n        \n        aura_env:ReadNote()\n    end\nend",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
