["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true\n        }\n    elseif event == \"LIQUID_DISPEL_EVENT\" then\n        local spellID, GUID = ...\n        \n        if spellID ~= 1222232 then return end -- Devourer's Ire\n        if GUID ~= WeakAuras.myGUID then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true\n        }\n        \n        return true\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and destGUID == WeakAuras.myGUID and spellID == 1222232 then -- Devourer's Ire\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    end\nend",
