["events"] = "PARTY_LEADER_CHANGED",
["custom"] = "function()\n    if UnitIsGroupLeader(\"player\") then\n        if aura_env.config.dungeon.enable then\n            local difficultyIndex = aura_env.config.dungeon.difficulty\n            if difficultyIndex == 1 then\n                SetDungeonDifficultyID(1)  -- Normal\n            elseif difficultyIndex == 2 then\n                SetDungeonDifficultyID(2)  -- Heroic\n            else\n                SetDungeonDifficultyID(23) -- Mythic\n            end\n        end\n\n        if aura_env.config.raid.enable then\n            local difficultyIndex = aura_env.config.raid.difficulty\n            if difficultyIndex == 1 then\n                SetRaidDifficulties(true, 14)  -- Normal\n            elseif difficultyIndex == 2 then\n                SetRaidDifficulties(true, 15)  -- Heroic\n            else\n                SetRaidDifficulties(true, 16)  -- Mythic\n            end\n        end\n\n        if aura_env.config.legacyRaidSize.enable then\n            local difficultyIndex = aura_env.config.legacyRaidSize.difficulty\n            if difficultyIndex == 1 then\n                SetRaidDifficulties(false, 3)  -- 10 Player\n            else\n                SetRaidDifficulties(false, 4)  -- 25 Player\n            end\n        end\n    end\nend",
