["Devourer's Ire dispel assignments (macro)"] = {
["outline"] = "OUTLINE",
["wagoID"] = "Rz5kTzQc7",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = true,
["width"] = 1,
["name"] = "음성 재생",
["useDesc"] = true,
["key"] = "tts",
["desc"] = "반짝임 색이 빨간색에서 녹색으로 바뀔 때 \"dispel\" 음성을 재생합니다.",
},
{
