["name"] = "빨간색 반짝임",
["useDesc"] = true,
["key"] = "redGlow",
["desc"] = "당신에게 지정된 디버프 대상자가 매크로를 누르기 전까진 프레임이 빨간색으로 반짝입니다.|n|n체크를 풀면 대상자가 매크로를 눌렀을 때만 프레임이 녹색으로 반짝입니다.",
},
{
["text"] = "AuraUpdater",
["type"] = "header",
["useName"] = true,
["width"] = 1,
},
{
["type"] = "toggle",
["default"] = false,
["width"] = 1,
["name"] = "앵커 무시",
["useDesc"] = true,
["key"] = "ignoreAnchor",
["desc"] = "체크하면 이 위크오라에는 앵커 설정이 무시됩니다.|n|n이렇게 설정하면 크기 조정과 같은 설정을 이것만 따로 할 수 있습니다.",
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
},
["finish"] = {
["hide_all_glows"] = true,
},
["init"] = {
["custom"] = "function aura_env:ReadNote()\n    aura_env.GUIDToHealerGUID = {} -- Maps player GUIDs to their preferred healer GUID\n    aura_env.backupHealerGUIDs = {} -- Sorted list of backup healers. Non-hard assigned healers have higher priority.\n    \n    local assignedHealerGUIDs = {}\n    \n    for _, line in LiquidWeakAuras:IterateNoteAssignment(\"Ire\") do\n        local GUIDs = LiquidWeakAuras:LineToGUIDArray(line)\n        \n        if next(GUIDs) then\n            local healerGUID\n            \n            -- First find the healer GUID\n            for _, GUID in ipairs(GUIDs) do\n                local unit = aura_env.GUIDToUnit[GUID]\n                local isHealer = UnitGroupRolesAssigned(unit) == \"HEALER\"\n                \n                if isHealer then\n                    healerGUID = GUID\n                    \n                    tInsertUnique(assignedHealerGUIDs, healerGUID)\n                    \n                    break\n                end\n            end\n            \n            -- Assign each GUID to be dispelled by the found healer\n            if healerGUID then\n                for _, GUID in pairs(GUIDs) do\n                    aura_env.GUIDToHealerGUID[GUID] = healerGUID\n                end\n            end\n        end\n    end\n    \n    -- Find unassigned healer GUIDs, they are first prio in the backup list\n    for unit in WA_IterateGroupMembers() do\n        local GUID = UnitGUID(unit)\n        local isVisible = UnitIsVisible(unit)\n        local isHealer = UnitGroupRolesAssigned(unit) == \"HEALER\"\n        local isAssigned = tContains(aura_env.GUIDToHealerGUID, GUID)\n        \n        if isVisible and isHealer and not isAssigned then\n            table.insert(aura_env.backupHealerGUIDs, GUID)\n        end\n    end\n    \n    table.sort(aura_env.backupHealerGUIDs)\n    table.sort(assignedHealerGUIDs)\n    \n    tAppendAll(aura_env.backupHealerGUIDs, assignedHealerGUIDs)\nend\n\nfunction aura_env:AssignHealer(allstates, GUID, healerGUID)\n    aura_env.lastDispelAssignmentTime[healerGUID] = GetTime()\n    \n    if healerGUID == WeakAuras.myGUID then\n        local targetUnit = aura_env.GUIDToUnit[GUID]\n        local targetName = UnitName(targetUnit)\n        \n        -- Hide regular state for target\n        local state = allstates[GUID]\n        \n        if state then\n            state.show = false\n            state.changed = true\n        end\n        \n        -- Create a green glow state for target\n        allstates[GUID .. \"dispel\"] = {\n            show = true,\n            changed = true,\n            macroPressed = true,\n            GUID = GUID,\n            unit = targetUnit\n        }\n        \n        SendChatMessage(string.format(\"%s의 해제 담당입니다\", targetName), \"RAID\")\n    end\n    \n    WeakAuras.ScanEvents(\"LIQUID_DEVOURERS_IRE_ASSIGNMENT\", GUID, healerGUID)\nend\n\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if event == \"LIQUID_PRIVATE_AURA_MACRO\" then\n        if C_UnitAuras.GetPlayerAuraBySpellID(1222232) and not aura_env.macroPressed then -- Devourer's Ire\n            aura_env.macroPressed = true\n            \n            SendChatMessage(\"포식자의 노여움 매크로 눌렀어요!\", \"RAID\")\n            \n            LiquidWeakAuras:Broadcast(\"LIQUID_DISPEL_EVENT\", 1222232, WeakAuras.myGUID) -- Devourer's Ire\n        end\n    elseif event == \"LIQUID_DISPEL_EVENT\" then\n        local spellID, GUID = ...\n        \n        if spellID ~= 1222232 then return end -- Devourer's Ire\n        \n        local assignedHealerGUID = aura_env.GUIDToHealerGUID[GUID]\n        \n        -- If the player that pressed their macro has a healer assigned to them, assign them if possible\n        if assignedHealerGUID then\n            local assignedHealerUnit = aura_env.GUIDToUnit[assignedHealerGUID]\n            local isAlive = not UnitIsDeadOrGhost(assignedHealerUnit)\n            \n            if isAlive then\n                aura_env:AssignHealer(allstates, GUID, assignedHealerGUID)\n                \n                return true\n            end\n        end\n        \n        -- If the assigned healer couldn't be chosen (because they are dead), choose a backup\n        -- First try to select a backup that hasn't been assigned a dispel in the past 8 seconds\n        -- and that is not affected themselves\n        for _, healerGUID in ipairs(aura_env.backupHealerGUIDs) do\n            local healerUnit = aura_env.GUIDToUnit[healerGUID]\n            local isAlive = not UnitIsDeadOrGhost(healerUnit)\n            local lastDispelAssignmentTime = aura_env.lastDispelAssignmentTime[healerGUID] or 0\n            local isAffected = WA_GetUnitDebuff(healerUnit, 1222232) -- Devourer's Ire\n            \n            if isAlive and not isAffected and lastDispelAssignmentTime < GetTime() - 8 then\n                aura_env:AssignHealer(allstates, GUID, healerGUID)\n                \n                return true\n            end\n        end\n        \n        -- Assign the highest priority backup healer (first in the array) that is alive/not affected\n        -- Basically the same as above, but don't check for last dispel assignment time\n        -- This should practically ever happen\n        for _, healerGUID in ipairs(aura_env.backupHealerGUIDs) do\n            local healerUnit = aura_env.GUIDToUnit[healerGUID]\n            local isAlive = not UnitIsDeadOrGhost(healerUnit)\n            local isAffected = WA_GetUnitDebuff(healerUnit, 1222232) -- Devourer's Ire\n            \n            if isAlive and not isAffected then\n                aura_env:AssignHealer(allstates, GUID, healerGUID)\n                \n                return true\n            end\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 1222232 then -- Devourer's Ire\n            if destGUID == WeakAuras.myGUID then\n                aura_env.macroPressed = false\n                \n                return\n            end\n            \n            -- If we are the assigned healer to dispel the target, glow their frame red\n            local assignedHealerGUID = aura_env.GUIDToHealerGUID[destGUID]\n            \n            if assignedHealerGUID == WeakAuras.myGUID then\n                allstates[destGUID] = {\n                    show = true,\n                    changed = true,\n                    macroPressed = false,\n                    GUID = destGUID,\n                    unit = aura_env.GUIDToUnit[destGUID]\n                }\n            end\n            \n            return true\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 1222232 then -- Devourer's Ire\n            for _, state in pairs(allstates) do\n                if state.GUID == destGUID then\n                    state.show = false\n                    state.changed = true\n                    \n                    return true\n                end\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.macroPressed = false\n        aura_env.lastDispelAssignmentTime = {} -- Healer GUIDs -> time they last got assigned to dispel someone\n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            local GUID = UnitGUID(unit)\n            \n            aura_env.GUIDToUnit[GUID] = unit\n        end\n        \n        aura_env:ReadNote()\n    end\nend\n\n\n\n",
["events"] = "ENCOUNTER_START, LIQUID_PRIVATE_AURA_MACRO, CLEU:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED, LIQUID_DISPEL_EVENT",
["check"] = "event",
["unit"] = "player",
["customVariables"] = "{\n    macroPressed = {\n        display = \"Macro pressed\",\n        type = \"bool\"\n    }\n}",
