["customSort"] = "function(a, b)\n    local indexA = a.region.state.index or 0\n    local indexB = b.region.state.index or 0\n    \n    if indexA ~= indexB then\n        return indexA < indexB\n    end\n    \n    local stacksA = a.region.state.stacks or 0\n    local stacksB = b.region.state.stacks or 0\n    \n    local initialTimeA = a.region.state.initialTime or 0\n    local initialTimeB = b.region.state.initialTime or 0\n    \n    local unitA = a.region.state.unit or \"\"\n    local unitB = b.region.state.unit or \"\"\n    \n    if stacksA ~= stackB then\n        return stacksA > stacksB\n    elseif initialTimeA ~= initialTimeB then\n        return initialTimeA < initialTimeB\n    else\n        return unitA < unitB\n    end\nend",
