["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local assignments = {\n            \"왼쪽\",\n            \"왼쪽\",\n            \"오른쪽\",\n            \"오른쪽\"\n        }\n        \n        for i = 1, 4 do\n            allstates[i] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 5,\n                expirationTime = GetTime() + 5 - (i - 1) * 0.2,\n                GUID = WeakAuras.myGUID,\n                assignment = assignments[i],\n                autoHide = true\n            }\n        end\n    elseif event == \"LIQUID_SOULFIRE_CONVERGENCE\" then\n        local GUID, assignment = ...\n        \n        allstates[GUID] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5,\n            expirationTime = GetTime() + 5,\n            GUID = GUID,\n            assignment = assignment,\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
