["customGrow"] = "function(new_positions, active_regions)\n    \n    local important_row, optional_row = 0, 0\n    \n    for i, region_data in ipairs(active_regions) do\n        \n        local reminder = region_data.region.state.reminder\n        \n        if reminder == \"Add\" or reminder == \"Remove\" then\n            new_positions[i] = {-25, -40 * important_row}\n            important_row = important_row + 1\n            \n        elseif reminder == \"Optional\" then\n            new_positions[i] = {40, -40 * optional_row}\n            optional_row = optional_row + 1\n        end\n        \n        if WeakAuras.IsOptionsOpen() and i > 6 then\n            break\n        end\n    end\nend",
