["frameStrata"] = 1,
["actions"] = {
["start"] = {
["custom"] = "local R = aura_env.region\nlocal _G = _G\n\n\n-- hide the aura icon, we only need it to look nice in the weakaura list\naura_env.region.icon:Hide()\n\n\n-- Color Codes\nlocal C = {\n    G={r=0.26, g=0.88, b=0.25}, -- guild color code\n    O={r=0.25, g=0.74, b=0.25}, -- officer color code\n} \n\n\n-- formatted status texts\nlocal S = {\n    [0] = '',\n    [1] = format(' |cffFFFFFF*|r|cffFF9900%s|r', \"AFK\"),\n    [2] = format(' |cffFFFFFF*|r|cffFF3333%s|r', \"DND\"),\n}\n\n\n\n-- list of online guild members\nlocal OnlineMembers = {}\nlocal function UpdateGuildList()\n    \n    wipe(OnlineMembers)\n    \n    for i = 1, GetNumGuildMembers() do\n        \n        local name, _, _, level, _, zone, _, _, connected, status, class, _, _, _, _, _, guid = GetGuildRosterInfo(i)\n        if not name then return end\n        \n        if connected then\n            \n            local _,_, n = string.find(name, \"(.*)%-.*$\")\n            \n            OnlineMembers[#OnlineMembers + 1] = {\n                name   = n,\n                level  = level,\n                zone   = zone,\n                class  = class,\n                status = S[status],\n                guid   = guid\n            }\n        end\n    end\nend\n\n\n-- prepare a Frame for EasyMenu\nlocal menuFrame = _G[aura_env.id..\"_MenuFrame\"]\nif menuFrame == nil then\n    menuFrame = CreateFrame(\"Frame\", aura_env.id..\"_MenuFrame\", UIParent, \"UIDropDownMenuTemplate\")\nend    \n\n\n-- display Guild Button Tooltip with GMOTD and a list of online Members and their location\nR:SetScript(\"OnEnter\", function()\n        \n        local guildName, _ = GetGuildInfo('player')\n        local total,online = GetNumGuildMembers()\n        \n        GameTooltip:SetOwner(R, \"ANCHOR_RIGHT\")\n        \n        -- Title\n        GameTooltip:AddDoubleLine(guildName, online..'/'..total, C.G.r,C.G.g,C.G.b, C.G.r,C.G.g,C.G.b)\n        GameTooltip:AddLine(' ')\n        \n        \n        -- Guild Message of the Day\n        local GMOTD = GetGuildRosterMOTD()\n        if GMOTD ~= '' then\n            GameTooltip:AddLine(GetGuildRosterMOTD(), C.O.r,C.O.g,C.O.b, 1)\n            GameTooltip:AddLine(' ')\n        end\n        \n        \n        --  Member List\n        UpdateGuildList()\n        local MyZone = GetZoneText()\n        for i, Member in ipairs(OnlineMembers) do\n            \n            if i > 50 then -- More then displayed online message                \n                GameTooltip:AddLine(' ')\n                GameTooltip:AddLine(format('and %d more ...', #OnlineMembers - 50))\n                break\n            end\n            \n            -- zone rgb (using poor and common item colors for ease)\n            local zr,zg,zb,_ = GetItemQualityColor((MyZone == Member.zone) and 1 or 0) \n            -- class rgb\n            local cr,cg,cb,_ = GetClassColor(Member.class)\n            \n            GameTooltip:AddDoubleLine(Member.name..Member.status, Member.zone,  cr,cg,cb,  zr,zg,zb)\n            \n        end\n        \n        \n        GameTooltip:Show()\n        \nend)\n\n\n-- hide tooltip\nR:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n\n\n-- click handler for the context menu, either invites or whispers someone\nlocal function ContextMenuClick (_, type, guid )\n    \n    menuFrame:Hide()\n    \n    local _, _, _, _, _, name, _ = GetPlayerInfoByGUID(guid)\n    \n    if type == 'whisper' then\n        \n        SetItemRef( 'player:'..name, format('|Hplayer:%1$s|h[%1$s]|h',name), 'LeftButton' )\n        \n    elseif type == 'invite' then\n        \n        local invite = GetDisplayedInviteType(guid)\n        if invite == 'INVITE' or invite == 'SUGGEST_INVITE' then \n            \n            C_PartyInfo.InviteUnit(name)\n            \n        elseif invite == 'REQUEST_INVITE' then \n            \n            C_PartyInfo.RequestInviteFromUnit(name)\n            \n        end\n        \n    end\nend\n\n\n-- skeleton for the EasyMenu Context Menu\nlocal ContextMenu = {\n    { text = 'invite' , hasArrow = true, notCheckable=true, menuList={}, padding=20 },\n    { text = 'whisper', hasArrow = true, notCheckable=true, menuList={}, padding=20 },\n}\n\n\n-- toggle button texture on mouse press\nR:SetScript(\"OnMouseDown\", function(self) self.texture:SetAtlas(\"quickjoin-button-friendslist-down\") end)\n\n\n-- toggles button texture and prepares and displays a context menu on right click\nR:SetScript(\"OnMouseUp\", function(self, button) \n        \n        self.texture:SetAtlas(\"quickjoin-button-friendslist-up\")\n        \n        if button == 'RightButton' then\n            \n            local InvMenu, WhiMenu = wipe(ContextMenu[1].menuList), wipe(ContextMenu[2].menuList)\n            local playerName = UnitName(\"player\")\n            \n            for _, Member in ipairs(OnlineMembers) do\n                \n                if Member.name ~= playerName then\n                    \n                    local _,_,_,classColorHex = GetClassColor(Member.class)\n                    \n                    if not UnitInParty(Member.name) and not UnitInRaid(Member.name) then\n                        \n                        InvMenu[#InvMenu+1] = {\n                            text = Member.name,\n                            notCheckable = true,\n                            func = ContextMenuClick,\n                            arg1 = 'invite',\n                            arg2 = Member.guid,\n                            colorCode = '|c'..classColorHex, padding=20\n                        }\n                    end\n                    \n                    WhiMenu[#WhiMenu+1] = {\n                        text = Member.name,\n                        notCheckable = true,\n                        func = ContextMenuClick,\n                        arg1 = 'whisper',\n                        arg2 = Member.guid,\n                        colorCode = '|c'..classColorHex, padding=20\n                    }\n                    \n                end\n                \n            end\n            \n            EasyMenu(ContextMenu, menuFrame, \"cursor\", 0, 0, \"MENU\")\n            \n        else ToggleGuildFrame() end\n        \n        \nend)",
["do_custom"] = true,
},
["init"] = {
["custom"] = "local R = aura_env.region\n\nif R:GetAttribute(\"Setup\") ~= true then\n    \n    R:SetAttribute(\"Setup\", true)\n    R:EnableMouse(true)\n    \n    local t = R:CreateTexture(nil,\"BACKGROUND\")\n    t:SetAtlas(\"quickjoin-button-friendslist-up\")\n    t:SetAllPoints(R)\n    t:SetVertexColor(0,1,0)\n    \n    R.texture = t\nend",
["do_custom"] = true,
},
