},
["preferToUpdate"] = false,
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    if not aura_env.state.say then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        SendChatMessage(aura_env.state.say, \"YELL\")\n    end\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["customTextUpdate"] = "update",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
["custom"] = "if aura_env.state.text then\n    LiquidWeakAuras:PlaySound(aura_env.state.text, \"Davis\")\nend",
["do_custom"] = true,
},
["finish"] = {
},
["init"] = {
["custom"] = "local INVERSE_SIZE = WeakAuras.GetData(aura_env.id).width\nlocal DURATION = 5\n\n-- 1: melee\n-- 2: healers\n-- 3: ranged\nlocal INVERSE_POSITIONS = {\n    [1] = {\n        {\n            {0, -1.1 * INVERSE_SIZE, \"아래쪽\"},\n            {0, 0, \"가운데\"},\n            {0, 1.1 * INVERSE_SIZE, \"위쪽\"},\n        },\n        {\n            {-0.5 * INVERSE_SIZE, -0.55 * INVERSE_SIZE, \"가운데\"},\n            {0.55 * INVERSE_SIZE, -0.5 * INVERSE_SIZE, \"오른쪽\"},\n            {-0.5 * INVERSE_SIZE, 0.55 * INVERSE_SIZE, \"위쪽\"},\n        },\n    },\n    [2] = {\n        {\n            {-0.45 * INVERSE_SIZE, -0.6 * INVERSE_SIZE, \"아래쪽\"},\n            {0.45 * INVERSE_SIZE, 0, \"가운데\"},\n            {-0.45 * INVERSE_SIZE, 0.6 * INVERSE_SIZE, \"위쪽\"},\n        },\n        {\n            {0, -1.1 * INVERSE_SIZE, \"아래쪽\"},\n            {0, 0, \"가운데\"},\n            {0, 1.1 * INVERSE_SIZE, \"위쪽\"},\n        },\n    },\n    [3] = {\n        {\n            {1.1 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"오른쪽\"},\n            {0, -0.1 * INVERSE_SIZE, \"가운데\"},\n            {-1.1 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"왼쪽\"},\n            \n        },\n        {\n            {0.6 * INVERSE_SIZE, 0.6 * INVERSE_SIZE, \"오른쪽\"},\n            {0, -0.6 * INVERSE_SIZE, \"가운데\"},\n            {-0.6 * INVERSE_SIZE, 0.6 * INVERSE_SIZE, \"왼쪽\"},\n            \n        },\n        {\n            {0.6 * INVERSE_SIZE, 0.6 * INVERSE_SIZE, \"오른쪽\"},\n            {0, -0.6 * INVERSE_SIZE, \"가운데\"},\n            {-0.6 * INVERSE_SIZE, 0.6 * INVERSE_SIZE, \"왼쪽\"},\n            \n        },\n        {\n            {1.6 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"오른쪽\"},\n            {0, -0.1 * INVERSE_SIZE, \"가운데\"},\n            {-1.6 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"왼쪽\"},\n            \n        },\n        {\n            {1.6 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"오른쪽\"},\n            {0, -0.1 * INVERSE_SIZE, \"가운데\"},\n            {-1.6 * INVERSE_SIZE, 0.15 * INVERSE_SIZE, \"왼쪽\"},\n        }\n    },\n}\n\nfunction aura_env:CreateStates(allstates, isInverse, phase, set)\n    local myIndex = aura_env.crushingAssignment\n    \n    -- If the player is affected by Inverse Gravity, decide index based on their role/range\n    if isInverse then\n        local rangeType = LiquidWeakAuras:Spec(\"player\")\n        local isHealer = UnitGroupRolesAssigned(\"player\") == \"HEALER\"\n        \n        if isHealer then\n            myIndex = 2\n        else\n            if rangeType == \"m\" then -- Melee\n                myIndex = 1\n            elseif rangeType == \"r\" then -- Ranged\n                myIndex = 3\n            end\n        end\n    end\n    \n    if not myIndex then return end\n    \n    local inversePositions = INVERSE_POSITIONS[phase][set]\n    \n    for index, position in ipairs(inversePositions) do\n        local text = inversePositions[index][3]\n        local assigned = index == myIndex\n        \n        allstates[index] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = DURATION,\n            expirationTime = GetTime() + DURATION,\n            index = index,\n            position = position,\n            assigned = assigned,\n            isInverse = isInverse,\n            say = isInverse and assigned and text,\n            text = assigned and text,\n            autoHide = true\n        }\n    end\nend\n\nfunction aura_env:ReadNote()\n    aura_env.crushingAssignment = nil\n    \n    for lineCount, line in LiquidWeakAuras:IterateNoteAssignment(\"Crushing\") do\n        if lineCount > 3 then return end\n        \n        local _, containsPlayerGUID = LiquidWeakAuras:LineToGUIDArray(line)\n        \n        if containsPlayerGUID then\n            aura_env.crushingAssignment = lineCount\n            \n            break\n        end\n    end\nend\n\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        aura_env.crushingAssignment = math.random(3)\n        \n        aura_env:CreateStates(allstates, math.random(2) == 1, math.random(3), math.random(2))\n    elseif event == \"LIQUID_ASSIGNMENT_EVENT\" then\n        local id = ...\n        \n        if id ~= aura_env.id then return end\n        \n        aura_env.set = aura_env.set + 1\n        aura_env.affected = {}\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        if aura_env.disabled then return end\n        \n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" then\n            if spellID == 1234244 then -- Inverse Gravity\n                -- This is just here to increase the set count\n                table.insert(aura_env.affected, destGUID)\n                \n                if #aura_env.affected == 1 then\n                    local id = aura_env.id\n                    \n                    C_Timer.After(1, function() WeakAuras.ScanEvents(\"LIQUID_ASSIGNMENT_EVENT\", id) end)\n                end\n                \n                if destGUID == WeakAuras.myGUID then\n                    aura_env:CreateStates(allstates, true, aura_env.phase, aura_env.set)\n                    \n                    return true\n                end\n            elseif spellID == 1234243 then -- Crushing Gravity\n                if not aura_env.crushingAssignment then return end\n                \n                if destGUID == WeakAuras.myGUID then\n                    aura_env:CreateStates(allstates, false, aura_env.phase, aura_env.set)\n                    \n                    return true\n                end\n            elseif spellID == 1246143 then -- Touch of Oblivion\n                aura_env.affected = {}\n                aura_env.phase = aura_env.phase + 1\n                aura_env.set = 1\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        if spellID ~= 1231716 then return end -- Extinguish the Stars\n        \n        aura_env.affected = {}\n        aura_env.phase = 3\n        aura_env.set = 1\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.disabled = LiquidWeakAuras:IsAssignmentsDisabled()\n        \n        aura_env.affected = {}\n        aura_env.phase = 0\n        aura_env.set = 1\n        \n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            aura_env.GUIDToUnit[UnitGUID(unit)] = unit\n        end\n        \n        aura_env:ReadNote()\n    end\nend",
["events"] = "ENCOUNTER_START, CLEU:SPELL_AURA_APPLIED, UNIT_SPELLCAST_SUCCEEDED:boss, LIQUID_ASSIGNMENT_EVENT",
["check"] = "event",
["unit"] = "player",
["customVariables"] = "{\n    assigned = {\n        display = \"Assigned\",\n        type = \"bool\"\n    },\n    isInverse = {\n        display = \"Inverse Gravity\",\n        type = \"bool\"\n    }\n}",
["custom_hide"] = "timed",
},
