["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        local stacks = math.random(10)\n        local amp = stacks * 20\n        \n        return 1000000 + math.random(5000000), stacks, amp and amp > 0 and string.format(\"+%d%%\", amp) or \"\"\n    end\n    \n    local states = aura_env.states\n    \n    if not states then return end\n    \n    local absorb = states[2] and states[2].tooltip1 and tonumber(states[2].tooltip1)\n    local stacks = states[3] and states[3].stacks\n    local amp = states[3] and states[3].tooltip1 and tonumber(states[3].tooltip1)\n    \n    return absorb, stacks, amp and amp > 0 and string.format(\"+%d%%\", amp) or \"\"\nend",
