["custom"] = "function(states,event,...)\n    local _,subevent,_,_,_,_,_,destGUID,destName,_,_,spellID = ...\n    \n    if subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_REFRESH\" then   \n        if spellID == 114018 and select(2,UnitClass(destName)) == \"ROGUE\" then \n            local id = destGUID..spellID\n            states[id] = states[id] or {}\n            local state = states[id]\n            local c,_,_,d,e = select(2, WA_GetUnitBuff(destName, spellID))      \n            state.name = WA_ClassColorName(destName) or destName\n            state.progressType = \"timed\";\n            state.icon = c;\n            state.duration = d;\n            state.expirationTime = e;\n            state.autohide = true;\n            state.changed = true;\n            state.show = true;\n            return true\n        end\n    elseif subevent == \"SPELL_AURA_REMOVED\" and spellID == 114018 then \n        local id = destGUID..spellID\n        local v = states[id]\n        if v then\n            v.show = false\n            v.changed = true\n            return true\n        end\n    end\nend",
