["custom"] = "aura_env.safespotTTS = {\n    \"safespot star\",\n    \"safespot circle\",\n    \"safespot diamond\",\n    \"safespot triangle\",\n    \"safespot moon\",\n    \"safespot square\",\n    \"safespot cross\",\n    \"safespot skull\",\n}",
