["P3 Devour assignments (say spam)"] = {
["outline"] = "OUTLINE",
["displayText_format_text_format"] = "none",
["wagoID"] = "Rz5kTzQc7",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        SendChatMessage(aura_env.state.say)\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "function aura_env:ReadNote()\n    aura_env.mark = nil\n    \n    for lineCount, line in LiquidWeakAuras:IterateNoteAssignment(\"Devour\") do\n        local _, containsPlayerGUID = LiquidWeakAuras:LineToGUIDArray(line)\n        \n        if containsPlayerGUID then\n            aura_env.mark = lineCount\n            \n            return\n        end\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
