},
["custom_type"] = "stateupdate",
["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_SPELLCAST_START\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        if spellID ~= 1233539 then return end -- Devour\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 7,\n            expirationTime = GetTime() + 7,\n            say = string.format(\"{rt%d} %d\", aura_env.mark, aura_env.mark),\n            autoHide = true\n        }\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env:ReadNote()\n    end\nend",
