},
["subeventSuffix"] = "_AURA_APPLIED",
["custom_type"] = "stateupdate",
["duration"] = "6",
["event"] = "Combat Log",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            index = math.random(3),\n            unit = \"player\",\n            autoHide = true\n        }\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 1227847 then -- The Hunt\n            aura_env.count = aura_env.count + 1\n            \n            if aura_env.count == 4 then\n                aura_env.count = 1\n            end\n            \n            allstates[destGUID] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 6,\n                expirationTime = GetTime() + 6,\n                index = aura_env.count,\n                unit = aura_env.GUIDToUnit[destGUID],\n                autoHide = true\n            }\n            \n            return true\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            aura_env.GUIDToUnit[UnitGUID(unit)] = unit\n        end\n    end\nend",
