["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(event)\n    if event == \"INSTANCE_ENCOUNTER_ENGAGE_UNIT\" then\n        if not aura_env.config.enable then return end\n        if aura_env.timer then return end\n        \n        local aura_env = aura_env\n        \n        aura_env.timer = C_Timer.NewTimer(\n            0.5,\n            function()                                 \n                aura_env.timer = nil\n                \n                for i = 1, 12 do\n                    local unit = \"boss\" .. i\n                    \n                    if UnitExists(unit) then\n                        local GUID = UnitGUID(unit)\n                        local npcID, _, spawnIndex = LiquidWeakAuras:CreatureInfo(GUID)\n                        local isArcaneCollector = npcID == 240905\n                        \n                        if isArcaneCollector then\n                            local existingMark = GetRaidTargetIndex(unit)\n                            local mark = aura_env.marks[spawnIndex + 1]\n                            \n                            if mark and existingMark ~= mark then\n                                SetRaidTarget(unit, mark)\n                            end                            \n                        end\n                    end\n                end\n            end\n        )\n    end\nend",
