["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    local text = aura_env.state and aura_env.state.say\n    \n    if text then\n        if not aura_env.last or aura_env.last < GetTime() - 1 then\n            aura_env.last = GetTime()\n            \n            SendChatMessage(text)\n        end\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.assignments = {\n    \"왼쪽 깨기\",\n    \"오른쪽 깨기\",\n    \"외곽으로\",\n    \"외곽으로\"\n}\n\naura_env.say = {\n    \"왼쪽\",\n    \"오른쪽\",\n    \"외곽 이동\",\n    \"외곽 이동\"\n}\n\n-- How the assignment is displayed on raid leader lists\naura_env.listDisplay = {\n    \"왼쪽\",\n    \"오른쪽\",\n    \"외곽\",\n    \"외곽\"\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
