["finish"] = {
},
["init"] = {
["custom"] = "local data = WeakAuras.GetData(aura_env.id)\naura_env.main_region = WeakAuras.GetRegion(data.parent)\n\nif aura_env.main_region then\n    \n    if not aura_env.region.ClassTalentFrameHook then\n        local aura_env = aura_env\n        \n        C_Timer.After(1,\n            function()\n                C_AddOns.LoadAddOn(\"Blizzard_PlayerSpells\")\n                PlayerSpellsFrame.TalentsFrame:HookScript(\"OnShow\",\n                    function()\n                        WeakAuras.ScanEvents(\"TALENTS_REMINDER_SHOW\", true)\n                    end\n                )\n                aura_env.region.ClassTalentFrameHook = true\n            end\n        )\n        \n        C_Timer.After(1,\n            function()\n                C_AddOns.LoadAddOn(\"Blizzard_PlayerSpells\")\n                PlayerSpellsFrame.TalentsFrame:HookScript(\"OnHide\",\n                    function()\n                        WeakAuras.ScanEvents(\"TALENTS_REMINDER_HIDE\", false)\n                    end\n                )\n                aura_env.region.ClassTalentFrameHook = true\n            end\n        )\n    end\nend",
["do_custom"] = true,
},
},
