["unit"] = "target",
["custom"] = "function(allstates, event, unit)\n    if event == \"UNIT_ABSORB_AMOUNT_CHANGED\" or event == \"NAME_PLATE_UNIT_ADDED\" then\n        local guid = UnitGUID(unit)\n        if guid then \n            local npcID = select(6, strsplit(\"-\", guid))\n            if npcID and npcID == \"242631\" and UnitAffectingCombat(unit) then\n                local absorb = UnitGetTotalAbsorbs(unit)\n                local guid = UnitGUID(unit)\n                if absorb and absorb > 0 then\n                    allstates:Update(guid, {\n                            progressType = \"static\",\n                            total = allstates:Get(guid, \"total\") or absorb,\n                            value = absorb\n                    })\n                else\n                    allstates:Remove(guid)\n                end\n            end\n        end\n    elseif event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local guid = UnitGUID(unit)\n        if guid then\n            local state = allstates[guid]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
