["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    local assignment = aura_env.states and aura_env.states[3] and aura_env.states[3].assignment\n    \n    if not assignment then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        SendChatMessage(assignment)\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/Rz5kTzQc7/22",
["actions"] = {
["start"] = {
["custom"] = "if aura_env.config.tts and not WeakAuras.IsOptionsOpen() then\n    LiquidWeakAuras:PlaySound(aura_env.state.assignment)\nend",
["do_custom"] = true,
},
["finish"] = {
},
["init"] = {
["custom"] = "function aura_env:ReadNote()\n    aura_env.assignments = {}\n    aura_env.backups = {}\n    \n    local lineCount = 0\n    \n    for _, line in LiquidWeakAuras:IterateNoteAssignment(\"Star\") do\n        local GUIDs = LiquidWeakAuras:LineToGUIDArray(line)\n        \n        if next(GUIDs) then\n            lineCount = lineCount + 1\n            \n            if lineCount <= 6 then\n                aura_env.assignments[lineCount] = {GUIDs[1], GUIDs[2]}\n            else\n                for _, GUID in ipairs(GUIDs) do\n                    tInsertUnique(aura_env.backups, GUID)\n                end\n            end\n        end\n    end\n    \n    aura_env.enabled = #aura_env.assignments > 1\nend",
["do_custom"] = true,
},
},
