["do_custom"] = false,
},
["init"] = {
["custom"] = "function getKeyname(keytext)\n    \n    -- Weakaura Verison\n    aura_env.keysvers = \"Version 3.0.1\"\n    --key itemid\n    aura_env.key_id = 180653\n    \n    \n    for bag = 0,4 do\n        for slot = 1,C_Container.GetContainerNumSlots(bag) do\n            local get_item_id = C_Container.GetContainerItemID(bag,slot)\n            \n            if  get_item_id == aura_env.key_id then\n                keytext = C_Container.GetContainerItemLink(bag,slot)\n            end\n        end\n    end\n    \n    if not keytext then\n        keytext = \"돌 없음!\";\n    else\n        return keytext\n    end\nend\n\n-----",
["do_custom"] = false,
},
},
