["colorFunc"] = "function(progress, ...)\n    local speedMultiplier = 1\n    local progress = (progress * speedMultiplier) % 1\n    if progress < 0.33 then\n        local r = 1.0 - (progress * 3)\n        local g = progress * 3\n        return r, g, 0, 1\n    elseif progress < 0.67 then\n        local newProgress = progress - 0.33\n        local g = 1.0 - (newProgress * 3)\n        local b = newProgress * 3\n        return 0, g, b, 1\n    else \n        local newProgress = progress - 0.67\n        local b = 1.0 - (newProgress * 3)\n        local r = newProgress * 3        \n        return r, 0, b, 1\n    end \nend",
