["displayText"] = "%c",
["customText"] = "function()\n    if C_ChallengeMode.IsChallengeModeActive() then\n        aura_env.UpdateRemainingPercentage()\n    else\n        aura_env.DisplayText = \"\"\n    end\n    \n    if WeakAuras.IsOptionsOpen() then\n        local randomP = math.random(1,100)\n        aura_env.DisplayText = randomP..\"%\"\n    end\n    \n    return aura_env.DisplayText\nend",
["yOffset"] = -5,
["anchorPoint"] = "BOTTOMLEFT",
["displayText_format_c_gcd_gcd"] = true,
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.DisplayText = \"\"\nlocal section = 1\nlocal dungeons = {}\nlocal dungeonID = 0\n\ndungeons = {\n    \n    -- [ARA] Ara-Kara, City of Echoes\n    [503] = {\n        {1, aura_env.config.ARA.BossOne},\n        {2, aura_env.config.ARA.BossTwo},\n        {3, aura_env.config.ARA.BossThree},\n    }, \n    \n    -- [DAWN] The Dawnbreaker\n    [505] = {\n        {1, aura_env.config.DAWN.BossOne},\n        {2, aura_env.config.DAWN.BossTwo},\n        {3, aura_env.config.DAWN.BossThree},\n    }, \n    \n    -- [PotSF] Priory of the Sacred Flame\n    [499] = {\n        {1, aura_env.config.PotSF.BossOne},\n        {2, aura_env.config.PotSF.BossTwo},\n        {3, aura_env.config.PotSF.BossThree},\n    }, \n    \n    -- [OFG] Operation: Floodgate\n    [525] = {\n        {1, aura_env.config.OFG.BossOne},\n        {2, aura_env.config.OFG.BossTwo},\n        {3, aura_env.config.OFG.BossThree},\n        {4, aura_env.config.OFG.BossFour},\n    }, \n    \n    -- [ECO] Eco-Dome Al'dani\n    [542] = {\n        {1, aura_env.config.ECO.BossOne},\n        {2, aura_env.config.ECO.BossTwo},\n        {3, aura_env.config.ECO.BossThree},\n    }, \n    \n    -- [HOA] Halls of Atonement\n    [378] = {\n        {1, aura_env.config.HOA.BossOne},\n        {2, aura_env.config.HOA.BossTwo},\n        {3, aura_env.config.HOA.BossThree},\n        {4, aura_env.config.HOA.BossFour},\n    }, \n    \n    -- [STREET] Tazavesh: Streets\n    [391] = {\n        {1, aura_env.config.STREET.BossOne},\n        {2, aura_env.config.STREET.BossTwo},\n        {3, aura_env.config.STREET.BossThree},\n        {4, aura_env.config.STREET.BossFour},\n        {5, aura_env.config.STREET.BossFive},\n    }, \n    \n    -- [GAMB] Tazavesh: Gambit\n    [392] = {\n        {1, aura_env.config.GAMB.BossOne},\n        {2, aura_env.config.GAMB.BossTwo},\n        {3, aura_env.config.GAMB.BossThree},\n    }, \n}\n\naura_env.SortDungeonData = function()\n    table.sort(dungeons[dungeonID], function (left, right)\n            return left[2] < right[2]\n    end)\nend\n\naura_env.Initiate = function()\n    local currentDungeonId = C_ChallengeMode.GetActiveChallengeMapID()\n    if currentDungeonId == nil or currentDungeonId == dungeonID then return end\n    \n    dungeons = dungeons\n    dungeonID = currentDungeonId\n    section = 1    \n    aura_env.SortDungeonData()\nend\n\naura_env.GetDungeonData = function()\n    local dungeonData = dungeons[dungeonID][section]\n    local bossID = dungeonData[1]\n    local neededPercent = dungeonData[2]\n    return bossID, neededPercent\nend\n\naura_env.ResetDungeon = function()\n    dungeons = dungeons\n    dungeonID = 0\nend\n\naura_env.UpdateRemainingPercentage = function()\n    local currentDungeonID = C_ChallengeMode.GetActiveChallengeMapID()\n    \n    if currentDungeonID == nil or dungeons[currentDungeonID] == nil then return end\n    aura_env.Initiate()\n    local currentPercentage = aura_env.GetCurrentPercentage()\n    \n    if dungeons[dungeonID] == nil or dungeons[dungeonID][section] == nil then return end\n    \n    while dungeons[dungeonID][section][2] <= 0 do\n        section = section + 1\n    end\n    \n    local bossID, neededPercent = aura_env.GetDungeonData()\n    \n    if C_ScenarioInfo.GetCriteriaInfo(bossID) then\n        local isBossKilled = C_ScenarioInfo.GetCriteriaInfo(bossID).completed\n        local remainingPercent = neededPercent - currentPercentage\n        \n        if remainingPercent < 0.05 and remainingPercent > 0.00 then \n            remainingPercent = 0.00\n        end\n        \n        local displayPercent = string.format(\"%.2f%%\", remainingPercent)\n        if remainingPercent > 0 and isBossKilled then\n            aura_env.DisplayText = \"|cFFFF0000\"..displayPercent..\"|r\"\n            \n        elseif remainingPercent > 0 and not isBossKilled then\n            aura_env.DisplayText = displayPercent\n            \n        elseif remainingPercent <= 0 and not isBossKilled then\n            aura_env.DisplayText = \"|cFF00FF00DONE|r\"     \n            \n        elseif remainingPercent <= 0 and isBossKilled then\n            aura_env.DisplayText = \"|cFF00FF00FINISHED|r\"\n            section = section + 1\n        end\n    end\nend\n\naura_env.GetCurrentPercentage = function()\n    local steps = select(3, C_Scenario.GetStepInfo())\n    local criteriaInfo = C_ScenarioInfo.GetCriteriaInfo(steps) or {}\n    local percent, total, current = criteriaInfo.quantity, criteriaInfo.totalQuantity, criteriaInfo.quantityString\n    \n    if current then\n        current = tonumber(string.sub(current, 1, string.len(current) - 1)) or 0\n        local currentPercent = (current / total) * 100 \n        \n        return currentPercent or 0\n    end\n    \n    return 0\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
