["Paralysis Enrage - Mythic+ Talents Reminder (Monk)"] = {
["iconSource"] = -1,
["wagoID"] = "xY-2DODYm",
["parent"] = "Icons - Mythic+ Talents Reminder (Monk)",
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["dynamicDuration"] = false,
["debuffType"] = "HELPFUL",
["unit"] = "player",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["duration"] = "30",
["event"] = "Chat Message",
["custom_type"] = "stateupdate",
["customDuration"] = "function(trigger)\n    local duration = aura_env.config[\"Duration\"]\n    \n    if duration > 0 then\n        local expirationTime = duration + GetTime()\n        \n        -- Make the aura expire after a certain time\n        return duration, expirationTime\n    else\n        -- Keep the aura visible indefinitely\n        return 1, 2, true\n    end\nend",
["spellIds"] = {
},
["events"] = "PLAYER_ENTERING_WORLD, ZONE_CHANGED_NEW_AREA, PLAYER_SPECIALIZATION_CHANGED, TRAIT_CONFIG_UPDATED, READY_CHECK, PLAYER_REGEN_DISABLED, TALENTS_REMINDER_SHOW, TALENTS_REMINDER_HIDE",
["custom"] = "function(allstates, event)\n    \n    local reminder\n    \n    if event == \"OPTIONS\" then\n        \n        reminder = aura_env.reminders[math.random(#aura_env.reminders)]\n        \n    elseif (\n        aura_env.config[\"General Settings\"][\"Untrigger Events\"][1] == true\n        and event == \"PLAYER_REGEN_DISABLED\"\n    ) or (\n        aura_env.config[\"General Settings\"][\"Untrigger Events\"][2] == true\n        and event == \"TALENTS_REMINDER_HIDE\"\n    ) then\n        \n        reminder = nil\n        \n    elseif event == \"PLAYER_ENTERING_WORLD\"\n    or event == \"ZONE_CHANGED_NEW_AREA\"\n    or event == \"PLAYER_SPECIALIZATION_CHANGED\"\n    or event == \"TRAIT_CONFIG_UPDATED\"\n    or (\n        aura_env.config[\"General Settings\"][\"Trigger Events\"][1] == true\n        and event == \"READY_CHECK\"\n    )\n    or (\n        aura_env.config[\"General Settings\"][\"Trigger Events\"][2] == true\n        and event == \"TALENTS_REMINDER_SHOW\"\n    )\n    or event == \"STATUS\" then\n        \n        local zone_id = select(8, GetInstanceInfo())\n        \n        if zone_id and aura_env.spell_id > 0 then\n            \n            local is_known = IsPlayerSpell(aura_env.spell_id)\n            local zone_score = aura_env.zones[zone_id]\n            \n            if zone_score then\n                \n                local scores\n                \n                -- Check if Xal'atath's Bargain has been selected\n                if aura_env.config[\"Mythic+ Affixes\"][\"Xal'atath\"] == 1 then\n                    scores = {zone_score, unpack(aura_env.WeeklyAffixesScore())}\n                else\n                    scores = {zone_score}\n                end\n                \n                if not aura_env.config[\"General Settings\"][\"Inverted\"] then\n                    local lowest_score = math.min(unpack(scores))\n                    \n                    if lowest_score == 1 then\n                        if not is_known then\n                            reminder = aura_env.reminders[1]\n                        end\n                    elseif lowest_score == 2 then\n                        if not is_known then\n                            reminder = aura_env.reminders[2]\n                        end\n                    elseif lowest_score == 3 then\n                        if is_known then\n                            reminder = aura_env.reminders[3]\n                        end\n                    end\n                else\n                    local highest_score = 1\n                    \n                    for i = 1, #scores do\n                        if scores[i] < 4 and scores[i] > highest_score then\n                            highest_score = scores[i]\n                            \n                            if highest_score == 3 then\n                                break\n                            end\n                        end\n                    end\n                    \n                    if highest_score == 3 then\n                        if is_known then\n                            reminder = aura_env.reminders[3]\n                        end\n                    elseif highest_score == 2 then\n                        if is_known then\n                            reminder = aura_env.reminders[2]\n                        end\n                    elseif highest_score == 1 then\n                        if not is_known then\n                            reminder = aura_env.reminders[1]\n                        end\n                    end\n                end\n            end\n        end\n    else\n        -- Ignore all events not handled above\n        return false\n    end\n    \n    if reminder then\n        \n        local duration = 0\n        \n        if event ~= \"TALENTS_REMINDER_SHOW\" then\n            duration = aura_env.config[\"General Settings\"][\"Duration\"]\n        end\n        \n        local progress_type, expiration_time\n        \n        if duration and duration > 0 then\n            \n            progress_type = \"timed\"\n            expiration_time = duration + GetTime()\n        else\n            progress_type = \"static\"\n            duration = nil\n            expiration_time = nil\n        end\n        \n        C_Spell.RequestLoadSpellData(aura_env.spell_id)\n        local title = C_Spell.GetSpellName(aura_env.spell_id)\n        local description = C_Spell.GetSpellDescription(aura_env.spell_id)\n        \n        local tooltip\n        \n        if title then\n            if description then\n                tooltip = WrapTextInColorCode(title, \"FFFFFFFF\") .. \"\\n\" .. description\n            else\n                tooltip = WrapTextInColorCode(title, \"FFFFFFFF\")\n            end\n        end\n        \n        \n        allstates[aura_env.spell_id] = {\n            show = true,\n            changed = true,\n            progressType = progress_type,\n            duration = duration,\n            expirationTime = expiration_time,\n            reminder = reminder,\n            tooltip = tooltip,\n            tooltipWrap = true,\n            autoHide = true,\n        }\n    else\n        allstates[aura_env.spell_id] = {\n            show = false,\n            changed = true,\n        }\n    end\n    \n    return true\nend",
["check"] = "event",
["custom_hide"] = "timed",
["names"] = {
},
["customVariables"] = "{\n    reminder = {\n        display = \"Reminder\",\n        type = \"string\",\n    }\n}",
