["custom"] = "aura_env.spell_id = 450432  -- Paralysis\n\naura_env.reminders = {\n    \"Add\",\n    \"Optional\",\n    \"Remove\",\n}\n\naura_env.zones = {\n    \n    -- Cataclysm\n    [670] = aura_env.config[\"Cataclysm\"][\"Grim Batol\"],\n    [657] = aura_env.config[\"Cataclysm\"][\"The Vortex Pinnacle\"],\n    [643] = aura_env.config[\"Cataclysm\"][\"Throne of the Tides\"],\n    \n    -- Mists of Pandaria\n    [960] = aura_env.config[\"Mists of Pandaria\"][\"Temple of the Jade Serpent\"],\n    \n    -- Warlords of Draenor\n    [1208] = aura_env.config[\"Warlords of Draenor\"][\"Grimrail Depot\"],\n    [1195] = aura_env.config[\"Warlords of Draenor\"][\"Iron Docks\"],\n    [1176] = aura_env.config[\"Warlords of Draenor\"][\"Shadowmoon Burial Grounds\"],\n    [1279] = aura_env.config[\"Warlords of Draenor\"][\"The Everbloom\"],\n    \n    -- Legion\n    [1501] = aura_env.config[\"Legion\"][\"Black Rook Hold\"],\n    [1677] = aura_env.config[\"Legion\"][\"Cathedral of Eternal Night\"],\n    [1571] = aura_env.config[\"Legion\"][\"Court of Stars\"],\n    [1466] = aura_env.config[\"Legion\"][\"Darkheart Thicket\"],\n    [1456] = aura_env.config[\"Legion\"][\"Eye of Azshara\"],\n    [1477] = aura_env.config[\"Legion\"][\"Halls of Valor\"],\n    [1492] = aura_env.config[\"Legion\"][\"Maw of Souls\"],\n    [1458] = aura_env.config[\"Legion\"][\"Neltharion's Lair\"],\n    [1651] = aura_env.config[\"Legion\"][\"Return to Karazhan\"],\n    [1753] = aura_env.config[\"Legion\"][\"Seat of the Triumvirate\"],\n    [1516] = aura_env.config[\"Legion\"][\"The Arcway\"],\n    [1493] = aura_env.config[\"Legion\"][\"Vault of the Wardens\"],\n    \n    -- Battle for Azeroth\n    [1763] = aura_env.config[\"Battle for Azeroth\"][\"Atal'Dazar\"],\n    [1754] = aura_env.config[\"Battle for Azeroth\"][\"Freehold\"],\n    [1762] = aura_env.config[\"Battle for Azeroth\"][\"Kings' Rest\"],\n    [2097] = aura_env.config[\"Battle for Azeroth\"][\"Operation: Mechagon\"],\n    [1864] = aura_env.config[\"Battle for Azeroth\"][\"Shrine of the Storm\"],\n    [1822] = aura_env.config[\"Battle for Azeroth\"][\"Siege of Boralus\"],\n    [1877] = aura_env.config[\"Battle for Azeroth\"][\"Temple of Sethraliss\"],\n    [1594] = aura_env.config[\"Battle for Azeroth\"][\"The MOTHERLODE!!\"],\n    [1841] = aura_env.config[\"Battle for Azeroth\"][\"The Underrot\"],\n    [1771] = aura_env.config[\"Battle for Azeroth\"][\"Tol Dagor\"],\n    [1862] = aura_env.config[\"Battle for Azeroth\"][\"Waycrest Manor\"],\n    \n    -- Shadowlands\n    [2291] = aura_env.config[\"Shadowlands\"][\"De Other Side\"],    \n    [2287] = aura_env.config[\"Shadowlands\"][\"Halls of Atonement\"],\n    [2290] = aura_env.config[\"Shadowlands\"][\"Mists of Tirna Scithe\"],\n    [2289] = aura_env.config[\"Shadowlands\"][\"Plaguefall\"],\n    [2284] = aura_env.config[\"Shadowlands\"][\"Sanguine Depths\"],\n    [2285] = aura_env.config[\"Shadowlands\"][\"Spires of Ascension\"],\n    [2286] = aura_env.config[\"Shadowlands\"][\"The Necrotic Wake\"],\n    [2293] = aura_env.config[\"Shadowlands\"][\"Theater of Pain\"],\n    \n    -- Dragonflight\n    [2526] = aura_env.config[\"Dragonflight\"][\"Algeth'ar Academy\"],\n    [2520] = aura_env.config[\"Dragonflight\"][\"Brackenhide Hollow\"],\n    [2579] = aura_env.config[\"Dragonflight\"][\"Dawn of the Infinite\"],\n    [2527] = aura_env.config[\"Dragonflight\"][\"Halls of Infusion\"],\n    [2519] = aura_env.config[\"Dragonflight\"][\"Neltharus\"],\n    [2515] = aura_env.config[\"Dragonflight\"][\"The Azure Vault\"],\n    [2516] = aura_env.config[\"Dragonflight\"][\"The Nokhud Offensive\"],\n    [2521] = aura_env.config[\"Dragonflight\"][\"Ruby Life Pools\"],\n    [2451] = aura_env.config[\"Dragonflight\"][\"Uldaman: Legacy of Tyr\"],\n    \n    -- The War Within\n    [2660] = aura_env.config[\"The War Within\"][\"Ara-Kara, City of Echoes\"],\n    [2669] = aura_env.config[\"The War Within\"][\"City of Threads\"],\n    [2662] = aura_env.config[\"The War Within\"][\"The Dawnbreaker\"],\n    [2652] = aura_env.config[\"The War Within\"][\"The Stonevault\"],\n    [2648] = aura_env.config[\"The War Within\"][\"The Rookery\"],\n    [2661] = aura_env.config[\"The War Within\"][\"Cinderbrew Meadery\"],\n    [2651] = aura_env.config[\"The War Within\"][\"Darkflame Cleft\"],\n    [2773] = aura_env.config[\"The War Within\"][\"Operation: Floodgate\"],\n    [2649] = aura_env.config[\"The War Within\"][\"Priory of the Sacred Flame\"],\n}\n\naura_env.affixes = {\n    [148] = aura_env.config[\"Mythic+ Affixes\"][\"Ascendant\"],\n    [160] = aura_env.config[\"Mythic+ Affixes\"][\"Devour\"],\n    [159] = aura_env.config[\"Mythic+ Affixes\"][\"Oblivion\"],\n    [158] = aura_env.config[\"Mythic+ Affixes\"][\"Voidbound\"],\n}\n\nfunction aura_env.WeeklyAffixesScore()\n    local weekly_affixes = {}\n    local affixes = C_MythicPlus.GetCurrentAffixes()\n    \n    if affixes then\n        for i, affix in ipairs(affixes) do\n            weekly_affixes[i] = aura_env.affixes[affix.id]\n        end\n    end\n    \n    return weekly_affixes\nend",
["do_custom"] = true,
},
