{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["event"] = "Combat Log",
["unit"] = "player",
["events"] = "INSTANCE_ENCOUNTER_ENGAGE_UNIT, UNIT_SPELLCAST_SUCCEEDED:boss, ENCOUNTER_START, CLEU:SPELL_AURA_APPLIED",
["subeventSuffix"] = "",
["check"] = "event",
["subeventPrefix"] = "",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 8.3,\n            expirationTime = GetTime() + 8.3,\n            autoHide = true\n        }\n    elseif event == \"INSTANCE_ENCOUNTER_ENGAGE_UNIT\" then\n        if not aura_env.intermission then return end\n        \n        for i = 1, 12 do\n            local unit = \"boss\" .. i\n            \n            if UnitExists(unit) then\n                local GUID = UnitGUID(unit)\n                local npcID = select(6, strsplit(\"-\", GUID))\n                \n                if npcID == \"240905\" then -- Arcane Collector\n                    return\n                end\n            end\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 8.3,\n            expirationTime = GetTime() + 8.3,\n            autoHide = true\n        }\n        \n        aura_env.intermission = false\n        \n        return true\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, _, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and (spellID == 1233415 or spellID == 1233076) then -- Mana Splinter/Dark Singularity\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                aura_env.intermission = false\n                \n                return true\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 1227631 then -- Arcane Expulsion\n            aura_env.intermission = true\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.intermission = false\n    end\nend",
