["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.zoneIdList = {}\naura_env.zoneGroupList = {}\naura_env.UpdateLists = function()\n    for _,v in pairs(aura_env.config.zoneList) do \n        local zoneId = v[\"zoneId\"]\n        if string.match(zoneId, \"g\") then\n            zoneId = zoneId:gsub(\"g\",\"\")\n            zoneId = tonumber(zoneId) or nil\n            if zoneId ~= nil then\n                aura_env.zoneGroupList[zoneId] = true\n            end\n            \n        else\n            zoneId = tonumber(zoneId) or nil\n            if zoneId ~= nil then\n                aura_env.zoneIdList[zoneId] = true\n            end\n            \n            \n        end\n        \n        if zoneId == nil and not WeakAuras.IsOptionsOpen() then\n            print(\"WeakAuras - Auto Brightness:\", '\"'..string.upper(v[\"zoneName\"])..'\"\\'s', \"Zone ID is not a number!\")\n        end\n        \n    end \nend\n\n\naura_env.ApplyDefaultBrightness = function()\n    SetCVar(\"Gamma\", aura_env.config.gammaDefault)\n    SetCVar(\"Brightness\", aura_env.config.brightnessDefault)\n    SetCVar(\"Contrast\", aura_env.config.contrastDefault)    \nend\n\naura_env.ApplyInstanceBrightness = function()\n    SetCVar(\"Gamma\", aura_env.config.gammaInstance)\n    SetCVar(\"Brightness\", aura_env.config.brightnessInstance)\n    SetCVar(\"Contrast\", aura_env.config.contrastInstance)\nend\n\naura_env.ApplyBrightness = function()    \n    local zoneId = C_Map.GetBestMapForUnit(\"player\")\n    if not zoneId then return false end\n    local zoneGroupId = C_Map.GetMapGroupID(zoneId)\n    \n    if aura_env.zoneIdList[zoneId] or aura_env.zoneGroupList[zoneGroupId] then\n        aura_env.ApplyInstanceBrightness()\n        \n    else\n        aura_env.ApplyDefaultBrightness()\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "",
["do_custom"] = false,
},
},
