["events"] = "UNIT_SPELLCAST_SUCCEEDED:boss, LIQUID_CUSTOM_EVENT",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 2,\n            expirationTime = GetTime() + 2,\n            count = math.random(aura_env.config.totalCount),\n            autoHide = true\n        }\n    elseif event == \"LIQUID_CUSTOM_EVENT\" then\n        local id, count = ...\n        \n        if id ~= aura_env.id then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 2,\n            expirationTime = GetTime() + 2,\n            count = count,\n            autoHide = true\n        }\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        if spellID ~= 1225319 then return end -- Galactic Smash\n        \n        local id = aura_env.id\n        \n        for i = 1, aura_env.config.totalCount do\n            C_Timer.After(2.7 + i * 2, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", id, i) end)\n        end\n    end\nend",
