["spellIds"] = {
},
["events"] = "LIQUID_STARKILLER_SWING_ASSIGNMENT, UNIT_SPELLCAST_SUCCEEDED:boss",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for i = 1, 2 do\n            local assignment = i == 1 and \"왼쪽\" or \"오른쪽\"\n            \n            allstates[assignment] = {\n                show = true,\n                changed = true,\n                GUID = UnitGUID(\"player\"),\n                assignment = assignment,\n                index = assignment\n            }\n        end\n    elseif event == \"LIQUID_STARKILLER_SWING_ASSIGNMENT\" then\n        local GUID, assignment = ...\n        \n        allstates[assignment] = {\n            show = true,\n            changed = true,\n            GUID = GUID,\n            assignment = assignment,\n            index = assignment\n        }\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        if spellID ~= 1226024 then return end -- Starkiller Swing\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        return true\n    end\nend",
