["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local set = math.random(3)\n        local myIndex = math.random(2)\n        \n        local assignment = myIndex == 1 and \"가까운 거\" or \"먼 거\"\n        \n        if set == 1 then\n            assignment = myIndex == 1 and \"앞에 왼쪽\" or myIndex == 2 and \"앞에 오른쪽\" or \"뒤쪽\"\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            assignment = assignment\n        }\n    elseif event == \"LIQUID_EXCESS_MASS_ASSIGNMENT\" then\n        local assignments, _, set = ...\n        local myIndex = tIndexOf(assignments, WeakAuras.myGUID)\n        \n        if myIndex then\n            local assignment = myIndex == 1 and \"가까운 거\" or \"먼 거\"\n            \n            if set == 1 then\n                assignment = myIndex == 1 and \"앞에 왼쪽\" or myIndex == 2 and \"앞에 오른쪽\" or \"뒤쪽\"\n            end\n            \n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                assignment = assignment\n            }\n            \n            return true\n        else -- Hide state\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    elseif event == \"LIQUID_EXCESS_MASS_HIDE\" then\n        local state = allstates[\"\"]\n        \n        if state then\n            state.show = false\n            state.changed = true\n            \n            return true\n        end\n    end\nend\n\n\n\n",
