["event"] = "Combat Log",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for index = 1, 3 do\n            allstates[index] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 6,\n                expirationTime = GetTime() + 3 + index,\n                index = index,\n                GUID = UnitGUID(\"player\"),\n                autoHide = true\n            }\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 1227847 then -- The Hunt\n            aura_env.count = aura_env.count + 1\n            \n            if aura_env.count == 4 then\n                aura_env.count = 1\n            end\n            \n            allstates[destGUID] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 6,\n                expirationTime = GetTime() + 6,\n                index = aura_env.count,\n                GUID = destGUID,\n                autoHide = true\n            }\n            \n            return true\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n    end\nend",
