["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "LIQUID2_FRACTILLUS_ASSIGNMENT, UNIT_SPELLCAST_SUCCEEDED:boss",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local lane = (math.floor(GetTime()) % 6) + 1\n        local assignmentType = \"SPAWN\"\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            assignmentType = assignmentType,\n            text = string.format(\"%s {rt%d}\", assignmentType == \"SPAWN\" and \"생성\" or \"파괴\", lane),\n            assigned = lane == aura_env.lane\n        }\n    elseif event == \"LIQUID2_FRACTILLUS_ASSIGNMENT\" then\n        local assignmentType, GUID, lane = ...\n        \n        if not lane then return end\n        if GUID ~= WeakAuras.myGUID then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            assignmentType = assignmentType,\n            text = string.format(\"%s {rt%d}\", assignmentType == \"SPAWN\" and \"생성\" or \"파괴\", lane),\n            assigned = lane == aura_env.lane\n        }\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 1233416 or spellID == 1220394 or spellID == 1231871 then -- Crystalline Eruption/Shattering Backhand/Shockwave Slam\n            for _, state in pairs(allstates) do\n                state.show = false\n                state.changed = true\n            end\n            \n            return true\n        end\n    end\nend\n\n\n",
["names"] = {
},
["check"] = "event",
["subeventPrefix"] = "SPELL",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{\n    assignmentType = {\n        display = \"Assignment type\",\n        type = \"select\",\n        values = {\n            SPAWN = \"Spawn\",\n            BREAK = \"Break\"\n        }\n    }\n}",
},
