["parent"] = "Fractillus - Miscellaneous",
["displayText"] = "%c",
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        local mark = aura_env.state and aura_env.state.mark\n        \n        if mark then\n            SendChatMessage(mark)\n        end\n    end\nend",
["yOffset"] = 0,
