},
["events"] = "TRIGGER:2:3, ENCOUNTER_START",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        aura_env.total = 100\n        aura_env.value = math.random(100)\n        \n        aura_env.duration = 30\n        aura_env.expirationTime = GetTime() + 30\n        \n        aura_env:UpdateState(allstates)\n    elseif event == \"TRIGGER\" then\n        local triggerNumber, triggerStates = ...\n        \n        if triggerNumber == 2 then -- Health\n            local triggerStateIndex = next(triggerStates)\n            local triggerState = triggerStateIndex and triggerStates[triggerStateIndex]\n            \n            if not triggerState then return end\n            \n            aura_env.total = triggerState.total\n            aura_env.value = triggerState.value\n            \n            aura_env:UpdateState(allstates)\n        else -- Timer\n            local triggerState = triggerStates and triggerStates[\"\"]\n            \n            if not triggerState then return end\n            \n            aura_env.duration = triggerState.duration\n            aura_env.expirationTime = triggerState.expirationTime\n            \n            aura_env:UpdateState(allstates)\n        end\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.total = nil\n        aura_env.value = nil\n        aura_env.duration = nil\n        aura_env.expirationTime = nil\n    end\nend",
