["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.heroicAssignments = {\n    [1] = {\n        RANGED = \"{rt2}\",\n        MELEE = \"{rt1}\",\n        TANK = \"{rt1}\",\n    },\n    [2] = {\n        RANGED = \"{rt2}\",\n        MELEE = \"{rt1}\",\n        TANK = \"{rt1}\",\n    },\n    [3] = {\n        RANGED = \"{rt2}\",\n        MELEE = \"{rt1}\",\n        TANK = \"{rt1}\",\n    }\n}\n\naura_env.mythicAssignments = {\n    [1] = {\n        RANGED = \"{rt1}\",\n        MELEE = \"{rt7}\",\n        TANK = \"{rt7}\",\n    },\n    [2] = {\n        RANGED = \"{rt1}\",\n        MELEE = \"{rt2}\",\n        TANK = \"{rt2}\",\n    },\n    [3] = {\n        RANGED = \"{rt8}\",\n        MELEE = \"{rt4}\",\n        TANK = \"{rt4}\",\n    }\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        aura_env.assignments = aura_env.mythicAssignments\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5,\n            expirationTime = GetTime() + 5,\n            assignment = aura_env.assignments[math.random(3)][\"MELEE\"],\n            autoHide = true\n        }\n    elseif event == \"LIQUID_GALACTIC_SMASH_ASSIGNMENT\" then\n        local set, assignmentType, duration = ...\n        local assignment = aura_env.assignments[set][assignmentType]\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = duration,\n            expirationTime = GetTime() + duration,\n            assignment = assignment,\n            autoHide = true\n        }\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        local _, _, difficultyID = ...\n        \n        aura_env.assignments = difficultyID == 16 and aura_env.mythicAssignments or aura_env.heroicAssignments\n    end\nend",
