["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local assigned = ((math.floor(GetTime()) % 6) + 1) == aura_env.lane\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            assigned = assigned\n        }\n    elseif event == \"LIQUID2_FRACTILLUS_ASSIGNMENT\" then\n        local _, GUID, lane = ...\n        \n        if not lane then return end\n        if GUID ~= WeakAuras.myGUID then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            assigned = lane == aura_env.lane\n        }\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 1233416 or spellID == 1220394 or spellID == 1231871 then -- Crystalline Eruption/Shattering Backhand/Shockwave Slam\n            for _, state in pairs(allstates) do\n                state.show = false\n                state.changed = true\n            end\n            \n            return true\n        end\n    end\nend",
