["custom"] = "function aura_env:UpdateState(allstates)\n    if not aura_env.total then return end\n    if not aura_env.duration then return end\n    \n    allstates[1] = {\n        show = true,\n        changed = true,\n        progressType = \"static\",\n        value = aura_env.value,\n        total = aura_env.total,\n        index = 1,\n        skipPosition = true,\n    }\n    \n    allstates[2] = {\n        show = true,\n        changed = true,\n        progressType = \"timed\",\n        duration = aura_env.duration,\n        expirationTime = aura_env.expirationTime,\n        timer = true,\n        index = 2,\n        autoHide = true\n    }\nend",
